try:
    print('>>> f = map')
    print('>>> x = 3')
    print('>>> y = type(1)')
    print('>>> f(x, y)')
    f = map
    x = 3
    y = type(1)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
